<script setup lang="ts">
import { emptyFields, invoiceStatus, toPaise, type Invoice } from '../../../shared/domain'
const route = useRoute(); const api = useApi(); const invoice = ref<Invoice | null>(null)
const draft = reactive({ ...emptyFields(), subtotal: '', tax: '', total: '' })
const acknowledged = ref(false); const acceptDifference = ref(false); const dirty = ref(false); const busy = ref(false); const error = ref(''); const documentError = ref(''); const documentUrl = ref(''); const loaded = ref(false); const confirmArchive = ref(false)
let timer: ReturnType<typeof setTimeout> | undefined; let alive = true; let polls = 0; const slowProcessing = ref(false)
const mismatch = computed(() => toPaise(draft.subtotal) + toPaise(draft.tax) !== toPaise(draft.total))
function setDraft(i: Invoice) { Object.assign(draft, { vendor: i.vendor, number: i.number, date: i.date, due: i.due, currency: i.currency, payment: i.payment, notes: i.notes, subtotal: (i.subtotal / 100).toFixed(2), tax: (i.tax / 100).toFixed(2), total: (i.total / 100).toFixed(2) }); acknowledged.value = false; acceptDifference.value = false }
async function loadDocument() {
  if (!invoice.value?.file || ['awaiting-upload', 'rejected'].includes(invoice.value.processing) || documentUrl.value) return
  try { const result = await api<{ url: string; type: string }>(`/invoices/${route.params.id}/document`); const res = await fetch(result.url, { credentials: result.url.startsWith('/') ? 'same-origin' : 'omit' }); if (!res.ok) throw new Error('Unable to load document'); const blob = await res.blob(); if (alive) documentUrl.value = URL.createObjectURL(new Blob([blob], { type: result.type })); documentError.value = '' } catch { documentError.value = 'The document could not be loaded. Try again.' }
}
async function refresh() {
  try { const i = await api<Invoice>(`/invoices/${route.params.id}`); if (!alive) return; invoice.value = i; if (!dirty.value) setDraft(i); await loadDocument(); if (i.processing === 'processing' && ++polls < 30) timer = setTimeout(refresh, 4000); else if (i.processing === 'processing') slowProcessing.value = true } catch (e: any) { error.value = e.message } finally { loaded.value = true }
}
async function save() {
  if (!invoice.value) return; busy.value = true; error.value = ''
  try {
    const amounts = { subtotal: toPaise(draft.subtotal), tax: toPaise(draft.tax), total: toPaise(draft.total) }
    if (Object.values(amounts).some(n => !Number.isSafeInteger(n))) throw new Error('Enter amounts with no more than two decimal places.')
    await api(`/invoices/${invoice.value.id}`, { method: 'PATCH', body: { ...draft, ...amounts, version: invoice.value.version, acknowledged: acknowledged.value, acceptDifference: acceptDifference.value } })
    dirty.value = false; await navigateTo('/invoices?saved=1')
  } catch (e: any) { error.value = e.message } finally { busy.value = false }
}
async function action(action: 'paid' | 'unpaid' | 'archive' | 'restore') {
  if (!invoice.value) return; busy.value = true; error.value = ''
  try { invoice.value = await api<Invoice>(`/invoices/${invoice.value.id}/action`, { method: 'POST', body: { action, version: invoice.value.version } }); dirty.value = false; setDraft(invoice.value); confirmArchive.value = false } catch (e: any) { error.value = e.message } finally { busy.value = false }
}
onBeforeRouteLeave(() => { if (dirty.value && !window.confirm('Discard your unsaved invoice changes?')) return false })
onMounted(refresh)
onUnmounted(() => { alive = false; clearTimeout(timer); if (documentUrl.value) URL.revokeObjectURL(documentUrl.value) })
</script>
<template><NuxtLink to="/invoices" class="back-link">← Back to invoices</NuxtLink><p v-if="error" class="error" role="alert">{{ error }} <button v-if="!invoice" class="text-link" @click="refresh">Retry</button></p><p v-if="!loaded" class="loading" role="status">Loading invoice…</p><template v-if="invoice"><div class="page-heading compact"><div><p class="eyebrow">{{ invoice.reviewed ? 'YOUR INVOICE RECORD' : 'CHECK BEFORE YOU CONFIRM' }}</p><h1>{{ invoice.reviewed ? invoice.vendor : 'Review invoice' }}</h1><p>Compare the document with the details before saving.</p></div><span class="badge" :data-status="invoiceStatus(invoice)">{{ invoiceStatus(invoice) }}</span></div><div class="record-actions"><button v-if="invoice.reviewed && !invoice.archived" class="button secondary" :disabled="busy || dirty" @click="action(invoice.payment === 'paid' ? 'unpaid' : 'paid')">Mark {{ invoice.payment === 'paid' ? 'unpaid' : 'paid' }}</button><button v-if="invoice.archived" class="button secondary" :disabled="busy" @click="action('restore')">Restore invoice</button><button v-else class="text-link" :disabled="busy || dirty" @click="confirmArchive = true">Archive invoice</button></div><div v-if="confirmArchive" class="warning" role="alert"><p>Archive this invoice? It will leave your active list, totals and reminders. You can restore it later.</p><div class="button-row"><button class="button" :disabled="busy" @click="action('archive')">Yes, archive</button><button class="button secondary" @click="confirmArchive = false">Keep invoice</button></div></div><p v-if="invoice.archived" class="warning">This invoice is archived. Restore it to make changes.</p><p v-if="invoice.processing === 'awaiting-upload'" class="warning">This upload was not completed. Return to Upload to try again; you can archive this incomplete record.</p><p v-if="invoice.processing === 'processing'" class="success-message" role="status">{{ slowProcessing ? 'Extraction is taking longer than expected. Enter the details manually or check the status again.' : 'Extracting invoice details… This page updates automatically. You may enter and confirm details manually while waiting.' }} <button v-if="slowProcessing" class="text-link" @click="polls = 0; slowProcessing = false; refresh()">Check status</button></p><p v-if="invoice.failure" class="warning">{{ invoice.failure }}</p><div class="review-grid"><section class="document-panel" aria-label="Original document"><div class="document-toolbar"><span>{{ invoice.file?.name || 'Document' }}</span><a v-if="documentUrl" :href="documentUrl" target="_blank" rel="noopener noreferrer" class="text-link">Open document ↗</a></div><div v-if="documentUrl" class="document-view"><iframe v-if="invoice.file?.type === 'application/pdf'" :src="documentUrl" title="Original invoice PDF"></iframe><img v-else :src="documentUrl" alt="Original supplier invoice"></div><div v-else class="empty-cell"><p>{{ documentError || 'Document preview is not available yet.' }}</p><button v-if="documentError" class="button secondary" @click="loadDocument">Reload document</button></div></section><form class="form-panel" @submit.prevent="save" @input="dirty = true"><div class="section-heading"><h2>{{ invoice.reviewed ? 'Saved details' : 'Invoice details' }}</h2><span class="muted">INR</span></div><ul v-if="invoice.extraction?.warnings.length" class="extraction-warnings"><li v-for="warning in invoice.extraction.warnings" :key="warning">{{ warning }}</li></ul><fieldset :disabled="busy || invoice.archived || ['awaiting-upload', 'rejected'].includes(invoice.processing)"><div class="fields"><label class="full">Supplier name<input v-model="draft.vendor" required maxlength="200"><small v-if="invoice.extraction?.confidence.vendor !== undefined" class="field-hint">OCR confidence: {{ Math.round(invoice.extraction.confidence.vendor) }}%</small></label><label>Invoice number<input v-model="draft.number" required maxlength="100"></label><label>Currency<select v-model="draft.currency"><option value="INR">INR · Indian rupee</option></select></label><label>Invoice date<input v-model="draft.date" type="date" required></label><label>Due date <span class="optional">(optional)</span><input v-model="draft.due" type="date"></label><label>Subtotal (₹)<input v-model="draft.subtotal" inputmode="decimal" required></label><label>Tax / GST (₹)<input v-model="draft.tax" inputmode="decimal" required></label><label>Total (₹)<input v-model="draft.total" inputmode="decimal" required></label><label>Payment status<select v-model="draft.payment"><option value="unpaid">Unpaid</option><option value="paid">Paid</option></select></label><label class="full">Notes <span class="optional">(optional)</span><textarea v-model="draft.notes" rows="3" maxlength="2000" placeholder="Payment terms, rounding, or a note for later"></textarea></label></div><label v-if="mismatch" class="check-label warning"><input v-model="acceptDifference" type="checkbox" required><span>Subtotal + GST differs from the total. I checked this difference against the document.</span></label><label class="check-label"><input v-model="acknowledged" type="checkbox" required><span>I reviewed the supplier, dates, amounts and payment status against the original document.</span></label><div class="form-actions"><NuxtLink to="/invoices" class="button secondary">Cancel</NuxtLink><button type="submit" class="button">{{ busy ? 'Saving…' : invoice.reviewed ? 'Save changes' : 'Confirm invoice' }} →</button></div></fieldset><p class="form-note">{{ dirty ? 'You have unsaved changes.' : 'Only confirmed invoices appear in your financial totals.' }}</p></form></div></template></template>
